use super::{between,ConnectorDocument,ConnectorFailure,ImageRequest};use crate::services::import_v2::url_policy::UrlPolicy;
pub fn extract(html:&str,url:&str)->Result<ConnectorDocument,ConnectorFailure>{let lower=html.to_ascii_lowercase();if lower.contains("环境异常")||lower.contains("verify")||lower.contains("访问过于频繁"){return Err(ConnectorFailure::Challenge)}if lower.contains("文章已被删除"){return Err(ConnectorFailure::Removed)}let title=between(html,"id=\"activity-name\">","</").map(str::trim).filter(|s|!s.is_empty()).ok_or(ConnectorFailure::StructureChanged)?;let body=between(html,"id=\"js_content\"", "</div>").ok_or(ConnectorFailure::EmptyBody)?;if body.trim().len()<8{return Err(ConnectorFailure::EmptyBody)}let target=UrlPolicy.normalize_for_session(url).map_err(|_|ConnectorFailure::StructureChanged)?;let mut images=Vec::new();let mut clean=body.to_string();for part in body.split("data-src=\"").skip(1){if let Some(raw)=part.split('"').next(){if let Ok(t)=UrlPolicy.normalize_for_session(raw){clean=clean.replace(raw,&t.public.public_url);images.push(ImageRequest{request_url:t.request_url.to_string(),public_url:t.public.public_url});}}}Ok(ConnectorDocument{title:title.into(),author:between(html,"id=\"js_name\">","</").map(|s|s.trim().into()),published_at:between(html,"var ct = \"","\"").map(str::to_string),body_html:clean,public_url:target.public.public_url,image_requests:images})}
